#[derive(Debug, Clone)]
struct DeleteRange {
    kind: String,
    remote: Option<String>, // None for local ranges, Some(remote) for remote ranges, Some("*") for wildcard
}

fn parse_delete_ranges(raw: Vec<String>) -> Vec<DeleteRange> {
    let mut result = Vec::new();
    for entry in raw {
        let parts: Vec<&str> = entry.split(':').collect();
        if parts.len() == 1 {
            result.push(DeleteRange { kind: parts[0].to_string(), remote: None });
        } else {
            let kind = parts[0].to_string();
            let remote = parts[1..].join(":");
            if kind == "merged" {
                // merged implies merged-local and merged-remote
                result.push(DeleteRange { kind: "merged-local".to_string(), remote: None });
                result.push(DeleteRange { kind: "merged-remote".to_string(), remote: Some(remote.clone()) });
            } else {
                result.push(DeleteRange { kind, remote: Some(remote) });
            }
        }
    }
    result
}

fn get_config_string(repo: &Repository, key: &str) -> Option<String> {
    if let Ok(cfg) = repo.config() {
        if let Ok(v) = cfg.get_string(key) {
            if !v.trim().is_empty() {
                return Some(v);
            }
        }
        // also try without? git config reads from multiple scopes; git2's get_string does that
        // But also need to try global? cfg.get_string already checks all.
    }
    None
}

fn get_config_bool(repo: &Repository, key: &str) -> Option<bool> {
    if let Ok(cfg) = repo.config() {
        if let Ok(v) = cfg.get_bool(key) {
            return Some(v);
        }
        if let Ok(s) = cfg.get_string(key) {
            match s.to_lowercase().as_str() {
                "true" | "yes" | "on" | "1" => return Some(true),
                "false" | "no" | "off" | "0" => return Some(false),
                _ => {}
            }
        }
    }
    None
}

fn get_config_u64(repo: &Repository, key: &str) -> Option<u64> {
    if let Ok(cfg) = repo.config() {
        if let Ok(v) = cfg.get_string(key) {
            if let Ok(n) = v.trim().parse::<u64>() {
                return Some(n);
            }
        }
    }
    None
}

fn glob_match(pattern: &str, text: &str) -> bool {
    // Use glob::Pattern
    if let Ok(pat) = glob::Pattern::new(pattern) {
        return pat.matches(text);
    }
    false
}

fn is_branch_protected(branch: &str, protected: &[String]) -> Option<String> {
    for pat in protected {
        if glob_match(pat, branch) {
            return Some(pat.clone());
        }
    }
    None
}

