fn delete_validator(s: &str) -> Result<String, String> {
    if s.is_empty() {
        return Err(format!("Invalid delete range format ``"));
    }
    let parts: Vec<&str> = s.split(':').collect();
    let (range, scope_opt) = if parts.len() == 1 {
        (parts[0], None)
    } else {
        let range = parts[0];
        let scope = parts[1..].join(":");
        (range, Some(scope))
    };
    if let Some(ref sc) = scope_opt {
        if sc.is_empty() || sc.trim().is_empty() {
            return Err(format!("Scope parse error for delete range while parsing scope: Scope is empty"));
        }
    }
    match range {
        "merged" => {
            if scope_opt.is_none() {
                return Err(format!("Invalid delete range format `merged`"));
            }
            Ok(s.to_string())
        },
        "merged-local" => {
            if scope_opt.is_some() {
                return Err(format!("Invalid delete range format `merged-local:origin`"));
            }
            Ok(s.to_string())
        },
        "merged-remote" => {
            if scope_opt.is_none() {
                return Err(format!("Invalid delete range format `merged-remote`"));
            }
            Ok(s.to_string())
        },
        "stray" => {
            if scope_opt.is_some() {
                let bad = if s.contains(':') { s } else { "stray:origin" };
                return Err(format!("Invalid delete range format `{}`", bad));
            }
            Ok(s.to_string())
        },
        "diverged" => {
            if scope_opt.is_none() {
                return Err(format!("Invalid delete range format `diverged`"));
            }
            Ok(s.to_string())
        },
        "local" => {
            if scope_opt.is_some() {
                let bad = if s.contains(':') { s } else { "local:origin" };
                return Err(format!("Invalid delete range format `{}`", bad));
            }
            Ok(s.to_string())
        },
        "remote" => {
            if scope_opt.is_none() {
                return Err(format!("Invalid delete range format `remote`"));
            }
            Ok(s.to_string())
        },
        _ => {
            return Err(format!("Invalid delete range format `{}`", s));
        }
    }
}

fn build_cli() -> Command {
    Command::new("executable")
        .bin_name("executable")
        .version("0.4.4")
        .disable_help_flag(true)
        .disable_version_flag(true)
        .arg(Arg::new("help-short").short('h').long("help").help("Print help (see a summary with '-h')").action(ArgAction::SetTrue))
        .arg(Arg::new("version").short('V').long("version").help("Print version").action(ArgAction::SetTrue))
        .arg(Arg::new("bases").short('b').long("bases").value_name("BASES").help("Comma separated multiple names of branches. All the other branches are compared with the upstream branches of those branches. [default: branches that tracks `git symbolic-ref refs/remotes/*/HEAD`] [config: trim.bases]").action(ArgAction::Append).value_delimiter(','))
        .arg(Arg::new("protected").short('p').long("protected").value_name("PROTECTED").help("Comma separated multiple glob patterns (e.g. `release-*`, `feature/*`) of branches that should never be deleted. [config: trim.protected]").action(ArgAction::Append).value_delimiter(','))
        .arg(Arg::new("no-update").long("no-update").help("Do not update remotes [config: trim.update]").action(ArgAction::SetTrue))
        .arg(Arg::new("update-interval").long("update-interval").value_name("UPDATE_INTERVAL").help("Prevents too frequent updates. Seconds between updates in seconds. 0 to disable. [default: 5] [config: trim.updateInterval]").default_value("5").value_parser(|s: &str| {
            if s.parse::<u64>().is_ok() {
                Ok(s.to_string())
            } else {
                Err(format!("invalid digit found in string"))
            }
        }))
        .arg(Arg::new("no-confirm").long("no-confirm").help("Do not ask confirm [config: trim.confirm]").action(ArgAction::SetTrue))
        .arg(Arg::new("no-detach").long("no-detach").help("Do not detach when HEAD is about to be deleted [config: trim.detach]").action(ArgAction::SetTrue))
        .arg(Arg::new("delete").short('d').long("delete").value_name("DELETE").help("Comma separated values of `<delete range>[:<remote name>]`. Delete range is one of the `merged, merged-local, merged-remote, stray, diverged, local, remote`. `:<remote name>` is only necessary to a `<delete range>` when the range is applied to remote branches. You can use `*` as `<remote name>` to delete a range of branches from all remotes. [default : `merged:origin`] [config: trim.delete]").action(ArgAction::Append).value_delimiter(',').value_parser(delete_validator))
        .arg(Arg::new("dry-run").long("dry-run").help("Do not delete branches, show what branches will be deleted").action(ArgAction::SetTrue))
}

