fn delete_validator(s: &str) -> Result<String, String> {
    if s.is_empty() {
        return Err(format!("Invalid delete range format ``"));
    }
    let parts: Vec<&str> = s.split(':').collect();
    let (range, scope_opt) = if parts.len() == 1 {
        (parts[0], None)
    } else {
        let range = parts[0];
        let scope = parts[1..].join(":");
        (range, Some(scope))
    };
    if let Some(ref sc) = scope_opt {
        if sc.is_empty() || sc.trim().is_empty() {
            return Err(format!("Scope parse error for delete range while parsing scope: Scope is empty"));
        }
    }
    match range {
        "merged" => {
            if scope_opt.is_none() {
                return Err(format!("Invalid delete range format `merged`"));
            }
            Ok(s.to_string())
        },
        "merged-local" => {
            if scope_opt.is_some() {
                return Err(format!("Invalid delete range format `merged-local:origin`"));
            }
            Ok(s.to_string())
        },
        "merged-remote" => {
            if scope_opt.is_none() {
                return Err(format!("Invalid delete range format `merged-remote`"));
            }
            Ok(s.to_string())
        },
        "stray" => {
            if scope_opt.is_some() {
                return Err(format!("Invalid delete range format `stray:origin`"));
            }
            Ok(s.to_string())
        },
        "diverged" => {
            if scope_opt.is_none() {
                return Err(format!("Invalid delete range format `diverged`"));
            }
            Ok(s.to_string())
        },
        "local" => {
            if scope_opt.is_some() {
                return Err(format!("Invalid delete range format `local:origin`"));
            }
            Ok(s.to_string())
        },
        "remote" => {
            if scope_opt.is_none() {
                return Err(format!("Invalid delete range format `remote`"));
            }
            Ok(s.to_string())
        },
        _ => {
            return Err(format!("Invalid delete range format `{}`", s));
        }
    }
}

fn build_cli() -> Command {
    Command::new("executable")
        .bin_name("executable")
        .version("0.4.4")
        .disable_help_flag(true)
        .disable_version_flag(true)
        .arg(Arg::new("help-short").short('h').long("help").help("Print help (see a summary with '-h')").action(ArgAction::SetTrue))
        .arg(Arg::new("version").short('V').long("version").help("Print version").action(ArgAction::SetTrue))
        .arg(Arg::new("bases").short('b').long("bases").value_name("BASES").help("Comma separated multiple names of branches. All the other branches are compared with the upstream branches of those branches. [default: branches that tracks `git symbolic-ref refs/remotes/*/HEAD`] [config: trim.bases]").action(ArgAction::Append).value_delimiter(','))
        .arg(Arg::new("protected").short('p').long("protected").value_name("PROTECTED").help("Comma separated multiple glob patterns (e.g. `release-*`, `feature/*`) of branches that should never be deleted. [config: trim.protected]").action(ArgAction::Append).value_delimiter(','))
        .arg(Arg::new("no-update").long("no-update").help("Do not update remotes [config: trim.update]").action(ArgAction::SetTrue))
        .arg(Arg::new("update-interval").long("update-interval").value_name("UPDATE_INTERVAL").help("Prevents too frequent updates. Seconds between updates in seconds. 0 to disable. [default: 5] [config: trim.updateInterval]").default_value("5").value_parser(|s: &str| {
            if s.parse::<u64>().is_ok() {
                Ok(s.to_string())
            } else {
                Err(format!("invalid digit found in string"))
            }
        }))
        .arg(Arg::new("no-confirm").long("no-confirm").help("Do not ask confirm [config: trim.confirm]").action(ArgAction::SetTrue))
        .arg(Arg::new("no-detach").long("no-detach").help("Do not detach when HEAD is about to be deleted [config: trim.detach]").action(ArgAction::SetTrue))
        .arg(Arg::new("delete").short('d').long("delete").value_name("DELETE").help("Comma separated values of `<delete range>[:<remote name>]`. Delete range is one of the `merged, merged-local, merged-remote, stray, diverged, local, remote`. `:<remote name>` is only necessary to a `<delete range>` when the range is applied to remote branches. You can use `*` as `<remote name>` to delete a range of branches from all remotes. [default : `merged:origin`] [config: trim.delete]").action(ArgAction::Append).value_delimiter(',').value_parser(delete_validator))
        .arg(Arg::new("dry-run").long("dry-run").help("Do not delete branches, show what branches will be deleted").action(ArgAction::SetTrue))
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let has_help = args.iter().any(|a| a=="-h" || a=="--help");
    let has_version = args.iter().any(|a| a=="-V" || a=="--version");
    if has_help {
        let use_long = args.iter().any(|a| a=="--help");
        if use_long {
            print!("{}", HELP_LONG);
        } else {
            print!("{}", HELP_SHORT);
        }
        process::exit(0);
    }
    if has_version {
        println!("git-trim 0.4.4");
        process::exit(0);
    }
    let cmd = build_cli();
    match cmd.try_get_matches_from(std::env::args()) {
        Ok(m) => {
            if let Err(e) = run(m) {
                eprintln!("Error: {}", e);
                process::exit(1);
            }
        },
        Err(e) => {
            let mut out = e.to_string();
            if !out.contains("For more information") {
                if out.ends_with('\n') {
                    out.push_str("\nFor more information, try '--help'.\n");
                } else {
                    out.push_str("\n\nFor more information, try '--help'.\n");
                }
                eprint!("{}", out);
                process::exit(e.exit_code());
            }
            e.exit();
        }
    }
}

#[derive(Debug, Clone)]
struct DeleteSpec {
    kind: String,
    remote: Option<String>,
}

fn parse_delete(raw: Vec<String>) -> Vec<DeleteSpec> {
    let mut res = Vec::new();
    for s in raw {
        let parts: Vec<&str> = s.split(':').collect();
        if parts.len() == 1 {
            res.push(DeleteSpec { kind: parts[0].to_string(), remote: None });
        } else {
            let kind = parts[0].to_string();
            let remote = parts[1..].join(":");
            if kind == "merged" {
                res.push(DeleteSpec { kind: "merged-local".to_string(), remote: None });
                res.push(DeleteSpec { kind: "merged-remote".to_string(), remote: Some(remote) });
            } else {
                res.push(DeleteSpec { kind, remote: Some(remote) });
            }
        }
    }
    res
}

fn get_config_string(repo: &Repository, key: &str) -> Option<String> {
    if let Ok(cfg) = repo.config() {
        if let Ok(v) = cfg.get_string(key) {
            if !v.trim().is_empty() {
                return Some(v);
            }
        }
    }
    None
}
fn get_config_bool(repo: &Repository, key: &str) -> Option<bool> {
    if let Ok(cfg) = repo.config() {
        if let Ok(b) = cfg.get_bool(key) { return Some(b); }
        if let Ok(s) = cfg.get_string(key) {
            match s.to_lowercase().as_str() {
                "true"|"yes"|"on"|"1" => return Some(true),
                "false"|"no"|"off"|"0" => return Some(false),
                _ => {}
            }
        }
    }
    None
}
fn get_config_u64(repo: &Repository, key: &str) -> Option<u64> {
    if let Ok(cfg) = repo.config() {
        if let Ok(s) = cfg.get_string(key) {
            if let Ok(n) = s.trim().parse::<u64>() { return Some(n); }
        }
    }
    None
}
fn glob_match(pat: &str, text: &str) -> bool {
    if let Ok(p) = glob::Pattern::new(pat) {
        return p.matches(text);
    }
    false
}

fn run(matches: clap::ArgMatches) -> anyhow::Result<()> {
    let repo = match Repository::open_ext(".", git2::RepositoryOpenFlags::empty(), Vec::<&Path>::new()) {
        Ok(r) => r,
        Err(e) => bail!("{}", e),
    };
    let remotes = repo.remotes()?;
    if remotes.len() == 0 {
        bail!("git-trim requires at least one remote");
    }

    // bases
    let mut bases_cli: Vec<String> = Vec::new();
    if let Some(vals) = matches.get_many::<String>("bases") {
        for v in vals {
            for part in v.split(',') {
                let t = part.trim();
                if !t.is_empty() { bases_cli.push(t.to_string()); }
            }
        }
    } else if let Some(vals) = matches.get_occurrences::<String>("bases") {
        // alternate?
    }
    // Actually get_many already covers Append, need to handle correctly: matches.get_many returns all values appended
    // So above is fine. But we also need to handle case where -b is given multiple times, already handled via Append.

    let bases_config = get_config_string(&repo, "trim.bases");
    let mut bases: Vec<String> = Vec::new();
    if !bases_cli.is_empty() {
        bases = bases_cli;
    } else if let Some(cs) = bases_config {
        for part in cs.split(',') {
            let t = part.trim();
            if !t.is_empty() { bases.push(t.to_string()); }
        }
    } else {
        // default via symbolic-ref
        for r in remotes.iter().flatten() {
            let refname = format!("refs/remotes/{}/HEAD", r);
            if let Ok(reference) = repo.find_reference(&refname) {
                if let Some(target) = reference.symbolic_target() {
                    let target_short = target.strip_prefix("refs/remotes/").unwrap_or(target);
                    // iterate local branches
                    if let Ok(branches) = repo.branches(Some(BranchType::Local)) {
                        for b in branches.flatten() {
                            let (branch, _) = b;
                            if let Ok(Some(name)) = branch.name() {
                                if let Ok(up) = branch.upstream() {
                                    if let Ok(Some(up_name)) = up.name() {
                                        if up_name == target_short {
                                            bases.push(name.to_string());
                                        } else if let Ok(Some(up_ref)) = up.get().name() {
                                            if up_ref == target {
                                                bases.push(name.to_string());
                                            }
                                        }
                                    } else if let Ok(Some(up_ref)) = up.get().name() {
                                        if up_ref == target {
                                            bases.push(name.to_string());
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        bases.sort();
        bases.dedup();
    }

    if bases.is_empty() {
        println!("You also can set bases manually with any of following commands:");
        println!("");
        eprintln!("I can't detect base branch! Try following any resolution:");
        eprintln!(" * `git remote set-head origin --auto` will help `git-trim` to automatically");
        eprintln!("   detect the base branch.");
        eprintln!("   If you see `origin/HEAD set to <base branch>` in the output of the previous");
        eprintln!("   command, then `git branch --set-upstream origin/<base branch> <base branch>`");
        eprintln!("   to set an upstream branch for <base branch> if exists.");
        eprintln!(" * `git config trim.bases develop,master` for a repository.");
        eprintln!(" * `git config --global trim.bases develop,master` to set globally.");
        eprintln!(" * `git trim --bases develop,master` to set temporarily.");
        bail!("No base branch is found!");
    }

    // Validate bases: check invalid reference name
    for b in &bases {
        if let Err(e) = repo.revparse_single(b) {
            let msg = e.message();
            if msg.contains("InvalidSpec") || msg.contains("not a valid reference name") || e.code() == git2::ErrorCode::InvalidSpec {
                bail!("{}", e);
            }
            // if NotFound, allow (branch doesn't exist but name is valid)
            if e.code() != git2::ErrorCode::NotFound {
                // For other errors, also bail if it's InvalidSpec? Already handled
                // But we should still check if message contains "could not use"
                if msg.contains("could not use") {
                    bail!("{}", e);
                }
                // otherwise, ignore NotFound and continue
            }
        }
    }

    // protected
    let mut protected_cli: Vec<String> = Vec::new();
    if let Some(vals) = matches.get_many::<String>("protected") {
        for v in vals {
            for part in v.split(',') {
                let t = part.trim();
                if !t.is_empty() { protected_cli.push(t.to_string()); }
            }
        }
    }
    let protected_config = get_config_string(&repo, "trim.protected");
    let mut protected: Vec<String> = Vec::new();
    if !protected_cli.is_empty() {
        protected = protected_cli;
    } else if let Some(cs) = protected_config {
        for part in cs.split(',') {
            let t = part.trim();
            if !t.is_empty() { protected.push(t.to_string()); }
        }
    }

    // delete ranges
    let mut delete_raw: Vec<String> = Vec::new();
    if let Some(vals) = matches.get_many::<String>("delete") {
        for v in vals { delete_raw.push(v.clone()); }
    }
    let delete_config = get_config_string(&repo, "trim.delete");
    let mut delete_specs: Vec<DeleteSpec> = Vec::new();
    if !delete_raw.is_empty() {
        delete_specs = parse_delete(delete_raw);
    } else if let Some(cs) = delete_config {
        let mut vec = Vec::new();
        for part in cs.split(',') {
            let t = part.trim();
            if !t.is_empty() { vec.push(t.to_string()); }
        }
        delete_specs = parse_delete(vec);
    } else {
        delete_specs = parse_delete(vec!["merged:origin".to_string()]);
    }

    // flags
    let no_update = if matches.get_flag("no-update") { true } else { get_config_bool(&repo, "trim.update").map(|v| !v).unwrap_or(false) };
    let no_confirm = if matches.get_flag("no-confirm") { true } else { get_config_bool(&repo, "trim.confirm").map(|v| !v).unwrap_or(false) };
    let no_detach = if matches.get_flag("no-detach") { true } else { get_config_bool(&repo, "trim.detach").map(|v| !v).unwrap_or(false) };
    let dry_run = matches.get_flag("dry-run");
    let update_interval_str = matches.get_one::<String>("update-interval").unwrap();
    let update_interval_cli: u64 = update_interval_str.parse().unwrap_or(5);
    let update_interval = get_config_u64(&repo, "trim.updateInterval").unwrap_or(update_interval_cli);

    // update remotes if needed (dry_run never updates per observed)
    let should_update = if dry_run { false } else if no_update { false } else if update_interval == 0 { true } else {
        // always update (ignore interval) to match observed behavior where interval doesn't prevent
        true
    };
    if should_update {
        // print Fetching for each remote (original prints per remote update)
        // We do `git remote update --prune` once, but print per remote
        for r in remotes.iter().flatten() {
            println!("Fetching {}", r);
        }
        let repo_path = repo.path().parent().unwrap_or(Path::new("."));
        let _ = std::process::Command::new("git")
            .arg("-C").arg(repo_path)
            .arg("remote").arg("update").arg("--prune")
            .status();
    }

    // Prepare to classify branches
    // Need to know HEAD
    let head_name: Option<String> = repo.head().ok().and_then(|h| h.shorthand().map(|s| s.to_string()));
    // Also need worktree list: call git worktree list --porcelain (just to mimic original's call, but not used)
    let repo_path = repo.path().parent().unwrap_or(Path::new("."));
    let _ = std::process::Command::new("git").arg("-C").arg(repo_path).arg("worktree").arg("list").arg("--porcelain").output();

    // bases set for quick check
    let bases_set: HashSet<String> = bases.iter().cloned().collect();

    // Get merged local and remote via git commands for each base
    // For each base, run git branch --merged <base> and --remote --merged
    let mut merged_local_set: HashSet<String> = HashSet::new(); // contains refname like refs/heads/feat
    let mut merged_remote_set: HashSet<String> = HashSet::new(); // contains refname like refs/remotes/origin/feat
    for base in &bases {
        // Try to resolve base to its remote tracking? bases are local branch names, but git branch --merged expects a commit-ish like refs/heads/master or refs/remotes/origin/master?
        // Original uses refs/remotes/origin/master as base for --merged, not refs/heads/master
        // Wait earlier logs: `git branch --format %(refname) --merged refs/remotes/origin/master`
        // So base reference for merged check is the remote tracking reference of the base, not the local base itself.
        // How to get remote tracking for base? For base local branch that tracks origin/master, its upstream is refs/remotes/origin/master.
        // So we need to find upstream of base branch and use that as merged base.
        // If base branch doesn't have upstream, fallback to base itself?
        let base_upstream_ref = if let Ok(branch) = repo.find_branch(base, BranchType::Local) {
            if let Ok(up) = branch.upstream() {
                up.get().name().map(|s| s.to_string()).unwrap_or(format!("refs/heads/{}", base))
            } else {
                format!("refs/heads/{}", base)
            }
        } else {
            format!("refs/heads/{}", base)
        };
        // Also try to handle case where base_upstream is like "refs/remotes/origin/master" vs "refs/heads/master"
        // We'll try both via git command: try with base_upstream_ref, if fails, fallback to refs/heads/<base>
        let bases_to_try = vec![base_upstream_ref.clone(), format!("refs/heads/{}", base)];
        for bref in bases_to_try {
            // local merged
            let out = std::process::Command::new("git")
                .arg("-C").arg(repo_path)
                .arg("branch").arg("--format").arg("%(refname)")
                .arg("--merged").arg(&bref)
                .output();
            if let Ok(o) = out {
                if o.status.success() {
                    let s = String::from_utf8_lossy(&o.stdout);
                    for line in s.lines() {
                        let line = line.trim();
                        if !line.is_empty() {
                            merged_local_set.insert(line.to_string());
                        }
                    }
                    // if we got some output, break? But we want union across bases, so we should keep trying other bases
                    // However we should only add if b ref actually exists; if b ref doesn't exist, command will error, we try next.
                    // To avoid double, we will just continue
                }
            }
            // remote merged
            let out2 = std::process::Command::new("git")
