    out = subprocess.run(["git","for-each-ref","--format=%(refname) %(objectname:short) %(upstream) %(upstream:short) %(HEAD)", "refs/heads"], cwd=repo_path, capture_output=True, text=True)
    local_branch_names = []
    local_up_map = {}
    local_head = None
    local_obj = {}
    for line in out.stdout.splitlines():
        # use git's for-each-ref with upstream may have empty, so tokens vary. We'll parse via splitting but need to handle HEAD marker "*"
        # Use a more robust method: call git branch --format and parse
        pass

    # Use git branch --format for local
