            line=line.rstrip("\n")
            # The line may have leading spaces? Use regex
            # Example: "refs/heads/master abc123 refs/remotes/origin/master origin/master *"
            # For non-current, HEAD is " "
            # So split
            # We can use shlex? Simpler: split and the last token is HEAD marker
            tokens = line.strip().split()
            # tokens: [refname, obj, upstream, upstream:short, HEAD?]
            # But upstream may be empty, so tokens length varies.
            # Use git for-each-ref instead for more reliable
            pass

    # Use for-each-ref for local with explicit format and handle empty upstream via |
    out = subprocess.run(["git","for-each-ref","--format=%(refname)|%(objectname:short)|%(upstream)|%(upstream:short)|%(HEAD)", "refs/heads"], cwd=repo_path, capture_output=True, text=True)
    local_branches = []  # list of dicts
    for line in out.stdout.splitlines():
        parts = line.split("|")
        # parts length 5, but HEAD part may be "*" or " "
        refname = parts[0] if len(parts)>0 else ""
        obj = parts[1] if len(parts)>1 else ""
        upstream_full = parts[2] if len(parts)>2 else ""
        upstream_short = parts[3] if len(parts)>3 else ""
        head_marker = parts[4] if len(parts)>4 else ""
        name = refname.replace("refs/heads/","",1)
        is_head = head_marker.strip() == "*"
        if is_head:
            head_name = name
        local_branches.append({
            "name": name,
            "ref": refname,
            "obj": obj,
            "upstream_full": upstream_full,
            "upstream_short": upstream_short,
            "is_head": is_head,
        })

    # remote branches
    out = subprocess.run(["git","for-each-ref","--format=%(refname)|%(objectname:short)|%(upstream) ", "refs/remotes"], cwd=repo_path, capture_output=True, text=True)
    remote_branches = []
    for line in out.stdout.splitlines():
        parts = line.split("|")
        refname = parts[0].strip() if len(parts)>0 else ""
        # refname like refs/remotes/origin/master
        if not refname:
