    head_branch = head_name
    # worktree list (call to mimic)
    subprocess.run(["git","worktree","list","--porcelain"], cwd=repo_path, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

    # protected check
    def is_protected(name):
        for pat in protected:
            try:
                if glob.fnmatch.fnmatch(name, pat):
                    return pat
                # also try Pattern
            except:
                pass
            # Use glob as fnmatch
            import fnmatch
            if fnmatch.fnmatch(name, pat):
                return pat
        return None

    # Use fnmatch for glob
    import fnmatch

    def protected_pat_for(name):
        for pat in protected:
            if fnmatch.fnmatch(name, pat):
