                remain_local.append((name, reason))
            else:
                # shouldn't remain if has_diverged
                remain_local.append((name, "diverged"))
        elif lb["stray"]:
            # stray but not deleted
            if lb["merged"]:
                if not has_merged_local:
                    reason = "merged, but: delete range `merged-local` was not given"
                    remain_local.append((name, reason))
                else:
                    remain_local.append((name, "stray"))
            else:
                if not has_stray:
                    reason = f"stray, but: delete range `stray` was not given"
                    remain_local.append((name, reason))
                else:
                    remain_local.append((name, "stray"))
        elif lb["merged"]:
            if lb["upstream_full"] or lb["upstream_short"]:
