                    remain_remote.append((short, "merged"))
            else:
                if rb["remote"] not in has_remote and "*" not in has_remote:
                    remain_remote.append((short, "*3"))
                else:
                    remain_remote.append((short, "merged"))
        else:
            # not merged
            # Should be *1?
            remain_remote.append((short, "*1"))

