      --dry-run
          Do not delete branches, show what branches will be deleted
  -h, --help
          Print help (see more with '--help')
  -V, --version
          Print version
"""

HELP_LONG = """Automatically trims your tracking branches whose upstream branches are merged or stray.
`git-trim` is a missing companion to the `git fetch --prune` and a proper, safer, faster alternative to your `<bash oneliner HERE>`.

Usage: executable [OPTIONS]

Options:
  -b, --bases <BASES>
          Comma separated multiple names of branches. All the other branches are compared with the upstream branches of those branches. [default: branches that tracks `git symbolic-ref refs/remotes/*/HEAD`] [config: trim.bases]

          The default value is a branch that tracks `git symbolic-ref refs/remotes/*/HEAD`. They might not be reflected correctly when the HEAD branch of your remote repository is changed. You can see the changed HEAD branch name with `git remote show <remote>` and apply it to your local repository with `git remote set-head <remote> --auto`.

  -p, --protected <PROTECTED>
          Comma separated multiple glob patterns (e.g. `release-*`, `feature/*`) of branches that should never be deleted. [config: trim.protected]

      --no-update
          Do not update remotes [config: trim.update]

      --update-interval <UPDATE_INTERVAL>
          Prevents too frequent updates. Seconds between updates in seconds. 0 to disable. [default: 5] [config: trim.updateInterval]

      --no-confirm
          Do not ask confirm [config: trim.confirm]

      --no-detach
          Do not detach when HEAD is about to be deleted [config: trim.detach]

  -d, --delete <DELETE>
          Comma separated values of `<delete range>[:<remote name>]`. Delete range is one of the `merged, merged-local, merged-remote, stray, diverged, local, remote`. `:<remote name>` is only necessary to a `<delete range>` when the range is applied to remote branches. You can use `*` as `<remote name>` to delete a range of branches from all remotes. [default : `merged:origin`] [config: trim.delete]

          `merged` implies `merged-local,merged-remote`.

          `merged-local` will delete merged tracking local branches. `merged-remote:<remote>` will delete merged upstream branches from `<remote>`. `stray` will delete tracking local branches, which is not merged, but the upstream is gone. `diverged:<remote>` will delete merged tracking local branches, and their upstreams from `<remote>` even if the upstreams are not merged and diverged from local ones. `local` will delete non-tracking merged local branches. `remote:<remote>` will delete non-upstream merged remote tracking branches. Use with caution when you are using other than `merged`. It might lose changes, and even nuke repositories.

      --dry-run
          Do not delete branches, show what branches will be deleted

  -h, --help
          Print help (see a summary with '-h')

  -V, --version
          Print version
"""

def delete_validator(s):
    if s == "":
        return (False, "Invalid delete range format ``")
    parts = s.split(":")
    if len(parts) == 1:
        rng = parts[0]
        scope = None
    else:
        rng = parts[0]
        scope = ":".join(parts[1:])
        if scope == "" or scope.strip() == "":
            return (False, "Scope parse error for delete range while parsing scope: Scope is empty")
    if rng == "merged":
        if scope is None:
            return (False, "Invalid delete range format `merged`")
        return (True, None)
    elif rng == "merged-local":
        if scope is not None:
            return (False, "Invalid delete range format `merged-local:origin`")
        return (True, None)
    elif rng == "merged-remote":
        if scope is None:
            return (False, "Invalid delete range format `merged-remote`")
        return (True, None)
    elif rng == "stray":
        if scope is not None:
            return (False, "Invalid delete range format `stray:origin`")
        return (True, None)
    elif rng == "diverged":
        if scope is None:
            return (False, "Invalid delete range format `diverged`")
        return (True, None)
    elif rng == "local":
        if scope is not None:
            return (False, "Invalid delete range format `local:origin`")
        return (True, None)
    elif rng == "remote":
        if scope is None:
            return (False, "Invalid delete range format `remote`")
        return (True, None)
    else:
        return (False, f"Invalid delete range format `{s}`")

def print_help(is_long):
    if is_long:
        sys.stdout.write(HELP_LONG)
    else:
        sys.stdout.write(HELP_SHORT)
    sys.exit(0)

def error_and_exit(msg, code=2):
    sys.stderr.write(msg)
    if not msg.endswith("\n"):
        sys.stderr.write("\n")
    if "For more information" not in msg:
        sys.stderr.write("\nFor more information, try '--help'.\n")
    sys.exit(code)

def parse_args():
    args = sys.argv[1:]
    has_short_help = "-h" in args
    has_long_help = "--help" in args
    has_version = "-V" in args or "--version" in args
    if has_long_help or has_short_help:
        print_help(has_long_help)
    if has_version:
        print("git-trim 0.4.4")
        sys.exit(0)

    bases = []
    protected = []
    no_update = False
    update_interval = "5"
    no_confirm = False
    no_detach = False
    delete_raw = []
    dry_run = False

    i = 0
    while i < len(args):
        a = args[i]
        if a == "-b" or a == "--bases":
            if i+1 >= len(args):
                error_and_exit(f"error: a value is required for '--bases <BASES>' but none was supplied")
            val = args[i+1]
            if val == "":
                i += 2
                continue
            for part in val.split(","):
                t = part.strip()
                if t != "":
                    bases.append(t)
            i += 2
        elif a.startswith("-b=") or a.startswith("--bases="):
            val = a.split("=",1)[1]
            if val == "":
                i += 1
                continue
            for part in val.split(","):
                t = part.strip()
                if t != "":
                    bases.append(t)
            i += 1
        elif a == "-p" or a == "--protected":
            if i+1 >= len(args):
                error_and_exit(f"error: a value is required for '--protected <PROTECTED>' but none was supplied")
            val = args[i+1]
            if val == "":
                i += 2
                continue
            for part in val.split(","):
                t = part.strip()
                if t != "":
                    protected.append(t)
            i += 2
        elif a.startswith("-p=") or a.startswith("--protected="):
            val = a.split("=",1)[1]
            if val == "":
                i += 1
                continue
            for part in val.split(","):
                t = part.strip()
                if t != "":
                    protected.append(t)
            i += 1
        elif a == "--no-update":
            no_update = True
            i += 1
        elif a == "--update-interval":
            if i+1 >= len(args):
                error_and_exit(f"error: a value is required for '--update-interval <UPDATE_INTERVAL>' but none was supplied")
            val = args[i+1]
            if val.startswith("-"):
                error_and_exit(f"error: unexpected argument '{val}' found\n\nUsage: executable [OPTIONS]")
            try:
                int(val)
            except ValueError:
                error_and_exit(f"error: invalid value '{val}' for '--update-interval <UPDATE_INTERVAL>': invalid digit found in string")
            update_interval = val
            i += 2
        elif a.startswith("--update-interval="):
            val = a.split("=",1)[1]
            if val.startswith("-"):
                error_and_exit(f"error: unexpected argument '-5' found\n\nUsage: executable [OPTIONS]")
            try:
                int(val)
            except ValueError:
                error_and_exit(f"error: invalid value '{val}' for '--update-interval <UPDATE_INTERVAL>': invalid digit found in string")
            update_interval = val
            i += 1
        elif a == "--no-confirm":
            no_confirm = True
            i += 1
        elif a == "--no-detach":
            no_detach = True
            i += 1
        elif a == "-d" or a == "--delete":
            if i+1 >= len(args):
                error_and_exit(f"error: a value is required for '--delete <DELETE>' but none was supplied")
            val = args[i+1]
            if val == "":
                error_and_exit(f"error: invalid value '' for '--delete <DELETE>': Invalid delete range format ``")
            parts = val.split(",")
            for part in parts:
                if part == "":
                    error_and_exit(f"error: invalid value '' for '--delete <DELETE>': Invalid delete range format ``")
                ok, err = delete_validator(part)
                if not ok:
                    error_and_exit(f"error: invalid value '{part}' for '--delete <DELETE>': {err}")
                delete_raw.append(part)
            i += 2
        elif a.startswith("-d=") or a.startswith("--delete="):
            val = a.split("=",1)[1]
            if val == "":
                error_and_exit(f"error: invalid value '' for '--delete <DELETE>': Invalid delete range format ``")
            parts = val.split(",")
            for part in parts:
                if part == "":
                    error_and_exit(f"error: invalid value '' for '--delete <DELETE>': Invalid delete range format ``")
                ok, err = delete_validator(part)
                if not ok:
                    error_and_exit(f"error: invalid value '{part}' for '--delete <DELETE>': {err}")
                delete_raw.append(part)
            i += 1
        elif a == "--dry-run":
            dry_run = True
            i += 1
        elif a.startswith("-"):
            error_and_exit(f"error: unexpected argument '{a}' found\n\nUsage: executable [OPTIONS]")
        else:
            error_and_exit(f"error: unexpected argument '{a}' found\n\nUsage: executable [OPTIONS]")
    return {
        "bases": bases,
        "protected": protected,
        "no_update": no_update,
        "update_interval": update_interval,
        "no_confirm": no_confirm,
        "no_detach": no_detach,
        "delete_raw": delete_raw,
        "dry_run": dry_run,
    }

def get_config(key):
    try:
        out = subprocess.run(["git","config","--get",key], capture_output=True, text=True)
        if out.returncode == 0:
            v = out.stdout.strip()
            if v != "":
                return v
    except:
        pass
    return None

def get_config_bool(key):
    try:
        out = subprocess.run(["git","config","--bool","--get",key], capture_output=True, text=True)
        if out.returncode == 0:
            v = out.stdout.strip().lower()
            if v in ("true","yes","on","1"):
                return True
            if v in ("false","no","off","0"):
                return False
        v = get_config(key)
        if v is not None:
            lv = v.lower()
            if lv in ("true","yes","on","1"):
                return True
            if lv in ("false","no","off","0"):
                return False
    except:
        pass
    return None

def main():
    opts = parse_args()
    # check repo
